41	const PROCESSING_FEE = 5;
42	/** Levied on every quote, not only the customer's first — see the policy-wide modifier rules. */
43	const INITIAL_ASSESSMENT_SURCHARGE = 0.1;
44	
45	/** The MHPCO price list; only the types pinned down by tests so far. */
46	const BASE_PREMIUMS: Record<string, number | undefined> = {
47	  sword: 100,
48	  amulet: 60,
49	  staff: 80,
50	  potion: 40,
51	  rune: 25,
52	  moonstone: 25,
53	};
54	
55	/** Keeps binary floating-point drift from tipping an exact amount over a rounding boundary. */
56	const withoutFloatNoise = (amount: number): number => Number(amount.toFixed(6));
57	
58	/** Premiums are rounded in the MHPCO's favour: up to the next whole G. */
59	const roundUpToWholeG = (amount: number): number => Math.ceil(withoutFloatNoise(amount));
60	
61	const basePremiumFor = (item: Item): number => {
62	  const basePremium = BASE_PREMIUMS[item.type];
63	  if (basePremium === undefined) throw new Error(`Unknown item type: ${item.type}`);
64	  return basePremium;
65	};
66	
67	const sumOf = <T>(values: T[], amountOf: (value: T) => number): number =>
68	  values.reduce((total, value) => total + amountOf(value), 0);
69	
70	/** A building block of 3 alike components is offered at a special base premium. */
71	const BLOCK_SIZE = 3;
72	const BLOCK_BASE_PREMIUM = 60;
73	
74	const alikeComponentGroups = (items: Item[]): Item[][] => [
75	  ...items
76	    .reduce(
77	      (groups, item) => groups.set(item.type, [...(groups.get(item.type) ?? []), item]),
78	      new Map<string, Item[]>(),
79	    )
80	    .values(),
81	];
82	
83	const basePremiumForGroup = (group: Item[]): number =>
84	  group.length === BLOCK_SIZE ? BLOCK_BASE_PREMIUM : sumOf(group, basePremiumFor);
85	
86	const HIGH_ENCHANTMENT_THRESHOLD = 5;
87	
88	const isCursed = (item: Item): boolean => item.cursed === true;
89	
90	const isHighlyEnchanted = (item: Item): boolean =>
91	  item.enchantment !== undefined && item.enchantment >= HIGH_ENCHANTMENT_THRESHOLD;
92	
93	/** Applicable surcharges stack additively on the item's own base premium. */
94	const SURCHARGE_RATES: { appliesTo: (item: Item) => boolean; rate: number }[] = [
95	  { appliesTo: isCursed, rate: 0.5 },
96	  { appliesTo: isHighlyEnchanted, rate: 0.3 },
97	];
98	
99	const surchargeRateFor = (item: Item): number =>
100	  sumOf(SURCHARGE_RATES, ({ appliesTo, rate }) => (appliesTo(item) ? rate : 0));
101	
102	/** Item-specific surcharges are levied on the affected item's own base premium. */
103	const surchargesFor = (item: Item): number =>
104	  basePremiumFor(item) * surchargeRateFor(item);
105	
106	const LOYALTY_THRESHOLD_YEARS = 2;
107	
108	const isLongStanding = (customer: Customer): boolean =>
109	  customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS;
110	
111	/** Policy-wide modifiers stack additively on the policy base premium. */
112	const POLICY_RATES: { appliesTo: (customer: Customer) => boolean; rate: number }[] = [
113	  { appliesTo: isLongStanding, rate: -0.2 },
114	  { appliesTo: () => true, rate: INITIAL_ASSESSMENT_SURCHARGE },
115	];
116	
117	const policyRateFor = (customer: Customer): number =>
118	  sumOf(POLICY_RATES, ({ appliesTo, rate }) => (appliesTo(customer) ? rate : 0));
119	
120	const quote = (step: QuoteStep, customer: Customer): StepResult => {
121	  const basePremium = sumOf(alikeComponentGroups(step.items), basePremiumForGroup);
122	  const surcharges = sumOf(step.items, surchargesFor);
123	  const policyBasePremium = basePremium + surcharges;
124	  const afterPolicyModifiers = policyBasePremium * (1 + policyRateFor(customer));
125	  return { premium: roundUpToWholeG(afterPolicyModifiers + PROCESSING_FEE) };
126	};
127	
128	const runStep = (step: Step, customer: Customer): StepResult => {
129	  if (step.op === "quote") return quote(step, customer);
130	  throw new Error(`Unsupported step: ${step.op}`);
131	};
132	
133	export const runScenario = (scenario: Scenario): ScenarioResult => ({
134	  results: scenario.steps.map((step) => runStep(step, scenario.customer)),
135	});
